#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maxThreeSumDivisibleByThree(vector<int>& nums) {
        vector<int> r0, r1, r2;
        for (int x : nums) {
            if (x % 3 == 0) r0.push_back(x);
            else if (x % 3 == 1) r1.push_back(x);
            else r2.push_back(x);
        }
        sort(r0.rbegin(), r0.rend());
        sort(r1.rbegin(), r1.rend());
        sort(r2.rbegin(), r2.rend());
        int ans = -1;
        if (r0.size() >= 3) ans = max(ans, r0[0] + r0[1] + r0[2]);
        if (r1.size() >= 3) ans = max(ans, r1[0] + r1[1] + r1[2]);
        if (r2.size() >= 3) ans = max(ans, r2[0] + r2[1] + r2[2]);
        if (!r0.empty() && !r1.empty() && !r2.empty()) {
            ans = max(ans, r0[0] + r1[0] + r2[0]);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxThreeSumDivisibleByThree(int[] nums) {
        List<Integer> r0 = new ArrayList<>(), r1 = new ArrayList<>(), r2 = new ArrayList<>();
        for (int x : nums) {
            if (x % 3 == 0) r0.add(x);
            else if (x % 3 == 1) r1.add(x);
            else r2.add(x);
        }
        r0.sort(Collections.reverseOrder());
        r1.sort(Collections.reverseOrder());
        r2.sort(Collections.reverseOrder());
        int ans = -1;
        if (r0.size() >= 3) ans = Math.max(ans, r0.get(0) + r0.get(1) + r0.get(2));
        if (r1.size() >= 3) ans = Math.max(ans, r1.get(0) + r1.get(1) + r1.get(2));
        if (r2.size() >= 3) ans = Math.max(ans, r2.get(0) + r2.get(1) + r2.get(2));
        if (!r0.isEmpty() && !r1.isEmpty() && !r2.isEmpty()) {
            ans = Math.max(ans, r0.get(0) + r1.get(0) + r2.get(0));
        }
        return ans;
    }
}

var maxThreeSumDivisibleByThree = function(nums) {
    const r0 = nums.filter(x => x % 3 === 0).sort((a, b) => b - a);
    const r1 = nums.filter(x => x % 3 === 1).sort((a, b) => b - a);
    const r2 = nums.filter(x => x % 3 === 2).sort((a, b) => b - a);
    let ans = -1;
    if (r0.length >= 3) ans = Math.max(ans, r0[0] + r0[1] + r0[2]);
    if (r1.length >= 3) ans = Math.max(ans, r1[0] + r1[1] + r1[2]);
    if (r2.length >= 3) ans = Math.max(ans, r2[0] + r2[1] + r2[2]);
    if (r0.length >= 1 && r1.length >= 1 && r2.length >= 1) {
        ans = Math.max(ans, r0[0] + r1[0] + r2[0]);
    }
    return ans;
};
